[{"event":"onClick","binding":"{() => {
                const a = document.createElement("a");
                a.href = `/api/contacts/blocked/export-csv`;
                a.download = `blocked-contacts-${new Date().toISOString().split("T")[0]}.csv`;
                document.body.appendChild(a);
